import type {SidebarsConfig} from '@docusaurus/plugin-content-docs';

// This runs in Node.js - Don't use client-side code here (browser APIs, JSX...)

/**
 * The bootcamp lessons are numbered directories with no sidebar_position and no
 * _category_.json, so an autogenerated category would order them
 * lesson-1, lesson-10, lesson-11, lesson-2... Listing them explicitly keeps the
 * numeric order. Lesson labels come from each page's `# Lesson N: ...` heading;
 * only the unit categories need an explicit label, because every unit index
 * shares the same frontmatter title.
 */
const bootcampUnits: {lessons: number; label: string}[] = [
  {lessons: 11, label: 'Module 1: Actor model introduction'},
  {lessons: 7, label: 'Module 2: Actors and messages'},
  {lessons: 6, label: 'Module 3: Lifecycles and state'},
  {lessons: 7, label: 'Module 4: Hierarchies and error handling'},
  {lessons: 6, label: 'Module 5: Message routing'},
  {lessons: 6, label: 'Module 6: Message channels'},
  {lessons: 3, label: 'Module 7: Proto.Actor Remote'},
  {lessons: 8, label: 'Module 8: Proto.Actor Cluster'},
  {lessons: 3, label: 'Module 9: Persistent actors'},
];

const bootcampCategories = bootcampUnits.map(({lessons, label}, index) => {
  const unit = index + 1;
  return {
    type: 'category' as const,
    label,
    link: {type: 'doc' as const, id: `bootcamp/unit-${unit}/index`},
    items: Array.from(
      {length: lessons},
      (_, lesson) => `bootcamp/unit-${unit}/lesson-${lesson + 1}/index`,
    ),
  };
});

